cp -n atlas.html atlas.html.bak_s1_1
python3 - <<'P'
import re
s=open('atlas.html',encoding='utf-8').read()
if 'nox-atlas-s1.js' not in s:
    main=open('atlas-s1.main.html',encoding='utf-8').read()
    s=re.sub(r'<main.*?</main>',lambda m:main,s,count=1,flags=re.S)
    s=s.replace('</head>','<link rel="stylesheet" href="/web/nox-atlas-s1.css?v=1"></head>',1)
    s=s.replace('</body>','<script type="module" src="/web/nox-atlas-s1.js?v=1"></script></body>',1)
    open('atlas.html','w',encoding='utf-8').write(s)
P
